USE [o-neil_db];
SET XACT_ABORT ON;
SET LOCK_TIMEOUT 30000;
BEGIN TRY
BEGIN TRANSACTION;
ALTER TABLE [o'neil].[order]]s detail] DROP CONSTRAINT [DF it's];
ALTER TABLE [o'neil].[order]]s detail] DROP CONSTRAINT [PK o]]neil];
ALTER TABLE [o'neil].[order]]s detail] ALTER COLUMN [it's code] nvarchar(50) COLLATE Latin1_General_100_CS_AS NOT NULL;
ALTER TABLE [o'neil].[order]]s detail] ADD CONSTRAINT [PK o]]neil] PRIMARY KEY CLUSTERED ([it's code] ASC) WITH (PAD_INDEX = OFF, IGNORE_DUP_KEY = OFF, STATISTICS_NORECOMPUTE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, DATA_COMPRESSION = NONE) ON [PRIMARY];
ALTER TABLE [o'neil].[order]]s detail] ADD CONSTRAINT [DF it's] DEFAULT (N'it''s') FOR [it's code];
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
THROW;
END CATCH;
